import * as fs from "fs";
import * as path from "path";

const DATA_DIR = path.join(__dirname, "..", "data");
const PROJECTS_FILE = path.join(DATA_DIR, "projects.json");
const TASKS_FILE = path.join(DATA_DIR, "tasks.json");

// Ensure data directory exists
if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

// Initialize empty arrays if files don't exist
if (!fs.existsSync(PROJECTS_FILE)) {
  fs.writeFileSync(PROJECTS_FILE, JSON.stringify([]));
}
if (!fs.existsSync(TASKS_FILE)) {
  fs.writeFileSync(TASKS_FILE, JSON.stringify([]));
}

interface Task {
  id: string;
  title: string;
  description?: string;
  status: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done";
  priority: "Low" | "Medium" | "High" | "Urgent";
  tags: string[];
  projectId: string;
  createdAt: number;
  updatedAt: number;
}

interface Project {
  id: string;
  name: string;
  createdAt: number;
  updatedAt: number;
}

class Store {
  private projects: Project[] = [];
  private tasks: Task[] = [];

  constructor() {
    this.load();
  }

  private load(): void {
    try {
      const projectsData = JSON.parse(fs.readFileSync(PROJECTS_FILE, "utf-8"));
      this.projects = projectsData || [];
    } catch {
      this.projects = [];
    }

    try {
      const tasksData = JSON.parse(fs.readFileSync(TASKS_FILE, "utf-8"));
      this.tasks = tasksData || [];
    } catch {
      this.tasks = [];
    }
  }

  private save(): void {
    fs.writeFileSync(PROJECTS_FILE, JSON.stringify(this.projects, null, 2));
    fs.writeFileSync(TASKS_FILE, JSON.stringify(this.tasks, null, 2));
  }

  // Projects
  getProjects(): Project[] {
    return this.projects;
  }

  getProject(id: string): Project | undefined {
    return this.projects.find((p) => p.id === id);
  }

  createProject(name: string): Project {
    const id = crypto.randomUUID();
    const now = Date.now();
    const project: Project = { id, name, createdAt: now, updatedAt: now };
    this.projects.push(project);
    this.save();
    return project;
  }

  updateProject(id: string, name: string): Project | undefined {
    const idx = this.projects.findIndex((p) => p.id === id);
    if (idx === -1) return undefined;
    const project = this.projects[idx];
    project.name = name;
    project.updatedAt = Date.now();
    this.save();
    return project;
  }

  deleteProject(id: string): boolean {
    // Also delete tasks belonging to this project
    this.tasks = this.tasks.filter((t) => t.projectId !== id);
    this.projects = this.projects.filter((p) => p.id !== id);
    this.save();
    return true;
  }

  // Tasks
  getTasks(): Task[] {
    return this.tasks;
  }

  getTask(id: string): Task | undefined {
    return this.tasks.find((t) => t.id === id);
  }

  getTasksByProject(projectId: string): Task[] {
    return this.tasks.filter((t) => t.projectId === projectId);
  }

  createTask(
    title: string,
    description?: string,
    status: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done" = "Backlog",
    priority: "Low" | "Medium" | "High" | "Urgent" = "Low",
    tags: string[] = [],
    projectId: string
  ): Task | undefined {
    // Validate title length
    if (title.length > 120) {
      throw new Error("Task title must not exceed 120 characters");
    }

    const project = this.getProject(projectId);
    if (!project) return undefined;

    const id = crypto.randomUUID();
    const now = Date.now();
    const task: Task = {
      id,
      title,
      description,
      status,
      priority,
      tags,
      projectId,
      createdAt: now,
      updatedAt: now,
    };
    this.tasks.push(task);
    this.save();
    return task;
  }

  updateTask(
    id: string,
    title?: string,
    description?: string,
    status?: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done",
    priority?: "Low" | "Medium" | "High" | "Urgent",
    tags?: string[]
  ): Task | undefined {
    const idx = this.tasks.findIndex((t) => t.id === id);
    if (idx === -1) return undefined;

    const task = this.tasks[idx];
    if (title !== undefined) {
      if (title.length > 120) {
        throw new Error("Task title must not exceed 120 characters");
      }
      task.title = title;
    }
    if (description !== undefined) {
      task.description = description;
    }
    if (status !== undefined) {
      task.status = status;
    }
    if (priority !== undefined) {
      task.priority = priority;
    }
    if (tags !== undefined) {
      task.tags = tags;
    }
    task.updatedAt = Date.now();
    this.save();
    return task;
  }

  deleteTask(id: string): boolean {
    const before = this.tasks.length;
    this.tasks = this.tasks.filter((t) => t.id !== id);
    if (this.tasks.length < before) this.save();
    return true;
  }

  searchTasks(
    projectId?: string,
    status?: "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done",
    priority?: "Low" | "Medium" | "High" | "Urgent",
    tag?: string,
    query?: string
  ): Task[] {
    let results = this.tasks;

    if (projectId) {
      results = results.filter((t) => t.projectId === projectId);
    }
    if (status) {
      results = results.filter((t) => t.status === status);
    }
    if (priority) {
      results = results.filter((t) => t.priority === priority);
    }
    if (tag) {
      results = results.filter((t) => t.tags.includes(tag));
    }
    if (query) {
      const q = query.toLowerCase();
      results = results.filter(
        (t) =>
          t.title.toLowerCase().includes(q) ||
          (t.description && t.description.toLowerCase().includes(q))
      );
    }

    // Sort by updatedAt descending, then createdAt descending
    results.sort((a, b) => {
      if (b.updatedAt !== a.updatedAt) return b.updatedAt - a.updatedAt;
      return b.createdAt - a.createdAt;
    });

    return results;
  }

  getStats(): {
    total: number;
    byStatus: Record<string, number>;
    byPriority: Record<string, number>;
  } {
    const all = this.tasks;
    const byStatus: Record<string, number> = {};
    const byPriority: Record<string, number> = {};

    for (const t of all) {
      byStatus[t.status] = (byStatus[t.status] || 0) + 1;
      byPriority[t.priority] = (byPriority[t.priority] || 0) + 1;
    }

    return {
      total: all.length,
      byStatus,
      byPriority,
    };
  }
}

