import express, { Request, Response, NextFunction } from "express";
import cors from "cors";
import * as http from "http";
import { store, type Task, type Project } from "./store";
import { setupSSE, broadcastProjectEvent, broadcastTaskEvent } from "./sse";

const app = express();
const PORT = 4317;

// Parse JSON bodies
app.use(express.json());

// CORS configuration
app.use(cors({ origin: "*" }));

// ==================== Projects Routes ====================

// GET /api/projects - list all projects
app.get("/api/projects", (req, res) => {
  res.json(store.getProjects());
});

// POST /api/projects - create a project
app.post("/api/projects", (req: Request, res: Response) => {
  try {
    const { name } = req.body;
    if (!name || typeof name !== "string" || name.trim() === "") {
      return res.status(400).json({ error: "Project name is required" });
    }
    const project = store.createProject(name.trim());
    broadcastProjectEvent("created", project);
    res.status(201).json(project);
  } catch (err) {
    res.status(500).json({ error: "Failed to create project" });
  }
});

// GET /api/projects/:id - get a single project
app.get("/api/projects/:id", (req: Request, res: Response) => {
  const project = store.getProject(req.params.id);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  res.json(project);
});

// PUT /api/projects/:id - update a project
app.put("/api/projects/:id", (req: Request, res: Response) => {
  const { name } = req.body;
  if (!name || typeof name !== "string" || name.trim() === "") {
    return res.status(400).json({ error: "Project name is required" });
  }
  const project = store.updateProject(req.params.id, name.trim());
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  broadcastProjectEvent("updated", project);
  res.json(project);
});

// DELETE /api/projects/:id - delete a project
app.delete("/api/projects/:id", (req: Request, res: Response) => {
  const project = store.getProject(req.params.id);
  if (!project) {
    return res.status(404).json({ error: "Project not found" });
  }
  store.deleteProject(req.params.id);
  broadcastProjectEvent("deleted", project);
  res.status(204).json({ id: req.params.id });
});

// ==================== Tasks Routes ====================

// GET /api/tasks - list tasks with filters and search
app.get("/api/tasks", (req: Request, res: Response) => {
  try {
    const {
      projectId,
      status,
      priority,
      tag,
      query,
    } = req.query;

    const tasks = store.searchTasks(
      projectId as string | undefined,
      status as "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done" | undefined,
      priority as "Low" | "Medium" | "High" | "Urgent" | undefined,
      tag as string | undefined,
      query as string | undefined
    );

    res.json(tasks);
  } catch (err) {
    res.status(500).json({ error: "Failed to fetch tasks" });
  }
});

// POST /api/tasks - create a task
app.post("/api/tasks", (req: Request, res: Response) => {
  try {
    const {
      title,
      description,
      status,
      priority,
      tags,
      projectId,
    } = req.body;

    if (!title || typeof title !== "string" || title.trim() === "") {
      return res.status(400).json({ error: "Task title is required" });
    }

    if (title.length > 120) {
      return res.status(400).json({ error: "Task title must not exceed 120 characters" });
    }

    if (!projectId) {
      return res.status(400).json({ error: "Project ID is required" });
    }

    const task = store.createTask(
      title.trim(),
      description,
      status as "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done",
      priority as "Low" | "Medium" | "High" | "Urgent",
      tags ? tags : [],
      projectId
    );

    if (!task) {
      return res.status(404).json({ error: "Project not found" });
    }

    broadcastTaskEvent("created", task);
    res.status(201).json(task);
  } catch (err: any) {
    if (err.message?.includes("120 characters")) {
      return res.status(400).json({ error: err.message });
    }
    res.status(500).json({ error: "Failed to create task" });
  }
});

// GET /api/tasks/:id - get a single task
app.get("/api/tasks/:id", (req: Request, res: Response) => {
  const task = store.getTask(req.params.id);
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }
  res.json(task);
});

// PUT /api/tasks/:id - update a task
app.put("/api/tasks/:id", (req: Request, res: Response) => {
  try {
    const {
      title,
      description,
      status,
      priority,
      tags,
    } = req.body;

    const task = store.updateTask(
      req.params.id,
      title?.trim(),
      description,
      status as "Backlog" | "Todo" | "In Progress" | "Blocked" | "Done" | undefined,
      priority as "Low" | "Medium" | "High" | "Urgent" | undefined,
      tags ? tags : []
    );

    if (!task) {
      return res.status(404).json({ error: "Task not found" });
    }

    broadcastTaskEvent("updated", task);
    res.json(task);
  } catch (err: any) {
    if (err.message?.includes("120 characters")) {
      return res.status(400).json({ error: err.message });
    }
    res.status(500).json({ error: "Failed to update task" });
  }
});

// DELETE /api/tasks/:id - delete a task
app.delete("/api/tasks/:id", (req: Request, res: Response) => {
  const task = store.getTask(req.params.id);
  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }
  store.deleteTask(req.params.id);
  broadcastTaskEvent("deleted", task);
  res.status(204).json({ id: req.params.id });
});

// ==================== Health check ====================
app.get("/api/health", (req: Request, res: Response) => {
  res.json({ status: "ok", timestamp: Date.now() });
});

// ==================== Error handlers ====================

// 404 handler
app.use((req: Request, res: Response) => {
  res.status(404).json({ error: "Not found" });
});

// General error handler
app.use((err: any, req: Request, res: Response, next: NextFunction) => {
  console.error("Unhandled error:", err);
  res.status(500).json({ error: "Internal server error" });
});

const server = app.listen(PORT, () => {
  console.log(`ForgeBoard backend listening on port ${PORT}`);
});

// Set up SSE
setupSSE(server);

export { app };

